<template>
  <view class="page"><view v-if="loading" class="state">加载中...</view><view v-else-if="error" class="state"><text>{{ error }}</text><button class="primary retry" @tap="load">重试</button></view><view v-else-if="order"><view class="card"><view class="row"><text class="title">订单号 {{ order.orderNo }}</text><text class="status">{{ order.statusText }}</text></view><text class="sub">下单时间 {{ order.createdAt }}</text></view><view class="card"><text class="section">商品信息</text><view v-for="item in goods" :key="item.id" class="goods"><image :src="item.image" mode="aspectFill"/><view><text class="name">{{ item.name }}</text><view class="row"><text class="sub">{{ item.spec }}</text><text>{{ item.pointsPrice }}积分 ×{{ item.quantity }}</text></view></view></view></view><view class="card"><text class="section">收货信息</text><text class="line">{{ order.consignee }} {{ order.phone }}</text><text class="line">{{ order.address }}</text></view><view class="card"><view class="row"><text>实付积分</text><text class="ui-strong">{{ order.totalPoints }} 积分</text></view><view v-if="order.payableCash>0" class="row"><text>现金补差</text><text class="ui-strong">¥{{ order.payableCashText }}</text></view></view><view v-if="order.logisticsCompany&&order.logisticsNo" class="card"><text class="section">物流信息</text><view class="row"><text>快递公司</text><text>{{ order.logisticsCompany }}</text></view><view class="row"><text>运单号</text><view><text>{{ order.logisticsNo }}</text><text class="copy" @tap="copy">复制</text></view></view></view><view v-if="order.status==='pending_payment'||order.status==='shipped'||order.logisticsNo" class="bottom"><view v-if="order.status==='pending_payment'" class="pay-summary"><text class="ui-small">待支付</text><text class="ui-strong">¥{{ order.payableCashText }}</text></view><button v-if="order.status==='pending_payment'" class="button ghost" @tap="cancel">取消订单</button><button v-if="order.status==='pending_payment'&&order.payableCash>0" class="button primary" @tap="pay">继续支付</button><button v-if="order.status==='shipped'" class="button ghost" @tap="logistics">查看物流</button><button v-if="order.status==='shipped'" class="button primary" @tap="copy">复制运单号</button></view></view></view>
</template>
<script>
import api from '../../common/api.js'
const statusText = status => ({ pending_send: '待发货', pending_payment: '待支付', paid: '已支付', shipped: '待收货', completed: '已完成', cancelled: '已取消', refunding: '退款审核中', refunded: '已退款' })[status] || '处理中'
const mask = value => { const text = String(value || ''); return text.length >= 7 ? `${text.slice(0,3)}****${text.slice(-4)}` : text }
export default { data() { return { id: '', loading: true, error: '', order: null, goods: [], paying: false } }, onLoad(options) { this.id = options.id ? decodeURIComponent(String(options.id)) : ''; if (this.id) this.load(); else { this.loading = false; this.error = '缺少订单参数' } }, methods: { async load() { this.loading = true; this.error = ''; try { const data = await api.getPointsOrderDetail(this.id); const cash = Number(data.payable_cash || data.payment_detail && data.payment_detail.payable_cash || 0); this.order = { id: data.id, orderNo: data.order_no, status: data.status, statusText: statusText(data.status), createdAt: data.created_at || '—', consignee: data.receiver_name || '—', phone: mask(data.receiver_phone), address: data.address_text || '—', totalPoints: Number(data.total_points) || 0, payableCash: cash, payableCashText: cash.toFixed(2), logisticsCompany: data.logistics_company || '', logisticsNo: data.logistics_no || '' }; this.goods = (data.items || []).map(item => ({ id: item.id, name: item.product_name || '积分商品', image: item.product_image || '/static/navigation/sravx-mark.png', spec: item.spec_text || '默认规格', quantity: Number(item.quantity) || 1, pointsPrice: Number(item.points_price) || 0 })) } catch (error) { this.error = error.message || '加载失败' } finally { this.loading = false } }, async pay() { if (this.paying || !this.order || this.order.status !== 'pending_payment' || !(this.order.payableCash > 0)) return; this.paying = true; try { uni.showLoading({ title: '调起支付...', mask: true }); const params = await api.createPaymentOrder({ orderId: this.order.id, orderType: 'points', description: this.goods[0] && this.goods[0].name || 'Sravx 积分订单' }); if (!params.timeStamp || !params.nonceStr || !params.package || !params.paySign) throw new Error('支付参数不完整，请稍后重试'); uni.hideLoading(); await uni.requestPayment({ timeStamp: params.timeStamp, nonceStr: params.nonceStr, package: params.package, signType: params.signType || 'RSA', paySign: params.paySign }); uni.showToast({ title: '支付成功', icon: 'success' }); this.load() } catch (error) { uni.hideLoading(); const message = error.errMsg || error.message || '支付失败'; uni.showToast({ title: message.includes('requestPayment:fail cancel') ? '已取消支付' : message, icon: 'none' }) } finally { this.paying = false } }, cancel() { uni.showModal({ title: '取消订单', content: '取消后将退回已扣积分并释放库存，确认取消吗？', confirmText: '确认取消', success: async ({ confirm }) => { if (!confirm) return; try { await api.cancelPointsOrder(this.order.id); uni.showToast({ title: '已取消', icon: 'success' }); this.load() } catch (error) { uni.showToast({ title: error.message || '取消失败', icon: 'none' }) } } }) }, logistics() { uni.navigateTo({ url: `/pages/order-logistics/index?orderId=${this.order.id}&orderNo=${encodeURIComponent(this.order.orderNo || '')}` }) }, copy() { if (this.order.logisticsNo) uni.setClipboardData({ data: this.order.logisticsNo, success: () => uni.showToast({ title: '已复制', icon: 'success' }) }) } } }
</script>
<style>
.page{min-height:100vh;padding:10px 10px 90px;box-sizing:border-box;background:#F4F6F8;color:#0B0D10}.state{padding:85px 20px;text-align:center;color:#636366}.retry{margin-top:16px}.card{margin-bottom:10px;padding:13px;border-radius:8px;background:#fff}.row{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:8px;font-size:12px}.card>.row:first-child{margin-top:0}.title,.section,.name{font-size:14px;font-weight:650}.section{display:block;margin-bottom:12px}.status,.ui-strong{color:#0B0D10;font-weight:650}.sub{display:block;margin-top:6px;color:#8e8e93;font-size:11px}.goods{display:flex}.goods image{width:70px;height:70px;border-radius:6px;background:#eee}.goods>view{display:flex;flex:1;margin-left:10px;flex-direction:column;justify-content:space-between}.line{display:block;margin-bottom:6px;font-size:12px}.copy{margin-left:8px;padding:2px 6px;border:1px solid #0B0D10;border-radius:3px;color:#0B0D10;font-size:11px}.bottom{position:fixed;bottom:0;left:0;right:0;display:flex;align-items:center;gap:8px;padding:10px 12px calc(10px + env(safe-area-inset-bottom));background:#fff;border-top:1px solid #eee}.pay-summary{min-width:70px}.pay-summary .ui-small,.pay-summary .ui-strong{display:block}.pay-summary .ui-small{color:#636366;font-size:10px}.button{flex:1;margin:0;border-radius:20px;font-size:13px;line-height:38px}.button::after,.primary::after{border:0}.ghost{border:1px solid #ddd;background:#fff;color:#666}.primary{background:#0B0D10;color:#fff}
</style>
